// <autogenerated />
using Microsoft.Build.Framework;
using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;

/// <summary>
/// Writes the Serenity static assets manifest (see Serenity.Web.SerenityStaticAssets): a JSON object with a
/// PatternSets array (each one a list of patterns) and a Folders array of the asset folders, with their BasePath,
/// Root, and Includes / Excludes / WellKnownExcludes as indexes into PatternSets, so that the (mostly same) pattern
/// lists are written only once. Patterns in item metadata are MSBuild style and relative to the project folder;
/// they are written relative to the asset folder (PatternFolder, e.g. wwwroot\** becomes **), with / separators.
/// Patterns that can't match files under the asset folder (other project folders like bin/**, absolute paths) are
/// left out, as are duplicates, and Includes when it would only be ** (all files). WellKnown is only written when
/// false. Folders without any pattern metadata (package folders, which only contain the files selected while
/// packing) are written with "Filter": false. The file is only written when its contents change.
/// </summary>
public class WriteStaticAssetsManifestTask : Microsoft.Build.Utilities.Task
{
    /// <summary>Asset folders, with BasePath and optional pattern metadata</summary>
    [Microsoft.Build.Framework.Required]
    public ITaskItem[] Roots { get; set; }

    [Microsoft.Build.Framework.Required]
    public string File { get; set; }

    /// <summary>The asset folder, relative to the project folder, that patterns are rooted at</summary>
    public string PatternFolder { get; set; } = "wwwroot";

    public override bool Execute()
    {
        var sets = new List<List<string>>();
        int SetIndex(List<string> patterns)
        {
            // order doesn't matter for matching (e.g. it differs by SDK for the same default excludes)
            var index = sets.FindIndex(x => x.Count == patterns.Count &&
                new HashSet<string>(x, StringComparer.OrdinalIgnoreCase).SetEquals(patterns));
            if (index < 0)
            {
                index = sets.Count;
                sets.Add(patterns);
            }
            return index;
        }

        var folders = new StringBuilder();
        for (var i = 0; i < Roots.Length; i++)
        {
            var root = Roots[i];
            folders.Append(i == 0 ? "\r\n    {" : ",\r\n    {");
            Append(folders, "BasePath", root.GetMetadata("BasePath"), first: true);
            Append(folders, "Root", root.GetMetadata("FullPath").Replace('\\', '/'));

            if (new[] { "Includes", "Excludes", "WellKnown", "WellKnownExcludes" }.All(x => string.IsNullOrEmpty(root.GetMetadata(x))))
            {
                folders.Append(", \"Filter\": false }");
                continue;
            }

            var includes = ToFolderPatterns(root.GetMetadata("Includes"));
            if (includes.Count > 0 && !(includes.Count == 1 && includes[0] == "**"))
                folders.Append(", \"Includes\": ").Append(SetIndex(includes));

            var excludes = ToFolderPatterns(root.GetMetadata("Excludes"));
            if (excludes.Count > 0)
                folders.Append(", \"Excludes\": ").Append(SetIndex(excludes));

            if (string.Equals(root.GetMetadata("WellKnown"), "true", StringComparison.OrdinalIgnoreCase))
            {
                var wellKnownExcludes = ToFolderPatterns(root.GetMetadata("WellKnownExcludes"));
                if (wellKnownExcludes.Count > 0)
                    folders.Append(", \"WellKnownExcludes\": ").Append(SetIndex(wellKnownExcludes));
            }
            else
                folders.Append(", \"WellKnown\": false");

            folders.Append(" }");
        }

        var sb = new StringBuilder();
        sb.Append("{\r\n  \"PatternSets\": [");
        for (var i = 0; i < sets.Count; i++)
        {
            sb.Append(i == 0 ? "\r\n    [" : ",\r\n    [");
            for (var j = 0; j < sets[i].Count; j++)
            {
                if (j > 0)
                    sb.Append(", ");
                AppendString(sb, sets[i][j]);
            }
            sb.Append("]");
        }
        sb.Append(sets.Count > 0 ? "\r\n  ],\r\n  \"Folders\": [" : "],\r\n  \"Folders\": [");
        sb.Append(folders);
        sb.Append(Roots.Length > 0 ? "\r\n  ]\r\n}\r\n" : "]\r\n}\r\n");

        var content = sb.ToString();
        if (System.IO.File.Exists(File) && System.IO.File.ReadAllText(File) == content)
            return true;

        var directory = Path.GetDirectoryName(File);
        if (!string.IsNullOrEmpty(directory))
            Directory.CreateDirectory(directory);

        System.IO.File.WriteAllText(File, content);
        return true;
    }

    private List<string> ToFolderPatterns(string patterns)
    {
        var prefix = (PatternFolder ?? "").Replace('\\', '/').Trim('/') + "/";
        var result = new List<string>();
        foreach (var raw in (patterns ?? "").Split(';'))
        {
            var pattern = raw.Trim().Replace('\\', '/');
            if (pattern.Length == 0)
                continue;

            if (prefix.Length > 1 && pattern.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
                pattern = pattern.Substring(prefix.Length);
            else if (!pattern.StartsWith("**/", StringComparison.Ordinal))
                continue;

            if (pattern.Length > 0 && !result.Contains(pattern, StringComparer.OrdinalIgnoreCase))
                result.Add(pattern);
        }

        return result;
    }

    private static void Append(StringBuilder sb, string name, string value, bool first = false)
    {
        sb.Append(first ? " \"" : ", \"").Append(name).Append("\": ");
        AppendString(sb, value);
    }

    private static void AppendString(StringBuilder sb, string value)
    {
        sb.Append('"');
        foreach (var c in value ?? "")
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\r': sb.Append("\\r"); break;
                case '\n': sb.Append("\\n"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < ' ')
                        sb.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                    else
                        sb.Append(c);
                    break;
            }
        }
        sb.Append('"');
    }
}
